
// index 0-7 map to:
// 0 Classic Beep, 1 Double Beep, 2 Chime, 3 Siren, 4 Alert,
// 5 Soft Chime (two ascending notes), 6 Warm Bell (long ring), 7 Double Pulse (two thumps)
const SOUNDS = [
  "data:audio/wav;base64,",
  "data:audio/wav;base64,",
  "data:audio/wav;base64,",
  "data:audio/wav;base64,",
  "data:audio/wav;base64,",
  "data:audio/wav;base64,",
  "data:audio/wav;base64,",
  "data:audio/wav;base64,"
];

// announce liveness + handle playback via runtime messaging ONLY
// (chrome.storage is NOT available in offscreen documents - using it kills
// this script at load, which is why the page never answered pings)
try { chrome.runtime.sendMessage({ action: "offscreenAlive" }); } catch (e) {}

chrome.runtime.onMessage.addListener((req, sender, sendResponse) => {
  if (req.action === "beepPing") {
    if (sendResponse) sendResponse({ pong: true });
    return true;
  }
  if (req.action === "playBeep") {
    const idx = (typeof req.soundId === "number" && SOUNDS[req.soundId]) ? req.soundId : 0;
    try {
      const a = new Audio(SOUNDS[idx]);
      a.addEventListener("playing", () => { if (sendResponse) sendResponse({ played: true }); });
      a.addEventListener("error", () => { if (sendResponse) sendResponse({ played: false, err: "audio error" }); });
      const p = a.play();
      if (p && p.catch) p.catch((err) => { if (sendResponse) sendResponse({ played: false, err: String(err) }); });
    } catch (err) {
      if (sendResponse) sendResponse({ played: false, err: String(err) });
    }
    return true; // async response
  }
});
